    ui.editSession({
      el: el,
      owner: wrap,
      get: function () { return el.value },
      set: function (v) {
        el.value = v == null ? '' : String(v)
        doWrite(el.value)
      },
      onCommit: o.onCommit,
      onCancel: o.onCancel,
    })

