        if (active) {
          ctx.save()
          ctx.globalAlpha = 0.22
          ctx.fillStyle = accent
          ctx.beginPath(); ctx.arc(p[0], p[1], r + Math.max(3, r * 0.8), 0, Math.PI * 2); ctx.fill()
          ctx.restore()
        }
