      if (selection.kind === 'column') { anchor.row = 0; focus.row = doc.rows.length - 1 }
      if (selection.kind === 'all') { anchor.row = 0; anchor.column = 0; focus.row = doc.rows.length - 1; focus.column = doc.columns.length - 1 }
